/// <reference types="node" />
import { readFileSync } from "node:fs"
import { describe, expect, it } from "vitest"
import { calm, checkTheme, crisp, defineTheme } from "./index"

// Same header as scripts/build-presets.mjs.
const header =
  "/* Generated by packages/theme/scripts/build-presets.mjs from src/builder/presets.ts. Do not edit. */\n"
const read = (file: string) => readFileSync(new URL(`../presets/${file}`, import.meta.url), "utf8")

describe("preset files", () => {
  it("calm.css equals a fresh build", () => {
    expect(read("calm.css")).toBe(header + defineTheme({ name: "calm", ...calm, root: true }).css)
  })

  it("crisp.css equals a fresh build", () => {
    expect(read("crisp.css")).toBe(header + defineTheme({ name: "crisp", ...crisp }).css)
  })
})

describe("presets pass strict", () => {
  it.each([
    ["calm", calm],
    ["crisp", crisp],
  ] as const)("%s: no failing pair in light or dark", (name, inputs) => {
    expect(() => defineTheme({ name, ...inputs })).not.toThrow()
    const report = checkTheme({ name, ...inputs })
    expect(report.ok).toBe(true)
    expect(report.pairs.filter((p) => !p.pass)).toEqual([])
    expect(new Set(report.pairs.map((p) => p.scheme))).toEqual(new Set(["light", "dark"]))
    expect(report.adjusted).toEqual([])
  })
})
